package com.asmj.marketplace.printout.model;
import lombok.*; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Data @Builder @NoArgsConstructor @AllArgsConstructor @Document("printout_requests")
public class PrintoutRequest { @Id private String id; private String requestNumber, customerId, vendorId, printoutServiceId, documentName, fulfilmentType, deliveryAddress, deliveryLandmark, deliveryCity, deliveryState, deliveryPincode, contactNumber, specialInstructions, vendorRemarks; private List<DocumentFile> files; private Integer copies,pageCount; private String printMode,paperSize,printSide,bindingType; private boolean laminationRequired; private BigDecimal printingAmount,bindingAmount,laminationAmount,deliveryCharge,totalAmount,quotedAmount; private String paymentStatus,paymentProofUrl,paymentProofPublicId,paymentReference; private Status status; private Instant createdAt,updatedAt; public enum Status { SUBMITTED,ACCEPTED,REJECTED,PRINTING,READY_FOR_PICKUP,OUT_FOR_DELIVERY,COMPLETED,CANCELLED } @Data @Builder @NoArgsConstructor @AllArgsConstructor public static class DocumentFile { private String fileName,url,publicId; } }
